 key=f'{country}.XG_FOB_USD.*.A'; url='https://api.imf.org/external/sdmx/3.0/data/dataflow/IMF.STA/IMTS/1.0.0/'+key+'?c[TIME_PERIOD]=ge:2000-01-01%2Ble:2024-12-31&attributes=all&detail=full&includeHistory=true&limit=5000'; now=datetime.now(timezone.utc).isoformat(); base=RAW/f'IMF_IMTS_{country}_XG_ALL_PARTNERS_2000_2024.csv'
